              h("span", { className: "yg-pill warn", style: { fontSize: "9px" } }, "🔒 " + (currentLang === "ru" ? "СЕЙФ DPAPI" : "VAULT DPAPI")),
              h("span", { style: { fontSize: "9.5px", color: "#fbbf24", fontFamily: "monospace" } }, "AES-256")
