              h("span", {
                style: { fontSize: "9.5px", color: threatActive ? "#f87171" : "#38bdf8", fontFamily: "monospace", fontWeight: 700 }
              }, threatActive ? (currentLang === "ru" ? "ИЗОЛЯЦИЯ" : "ISOLATED") : (currentLang === "ru" ? "ЗАЩИЩЕНО" : "SECURED"))
